      <div class="mk-stack" role="img" aria-label="${K.esc(`${K.t('good')} ${x.good}, ${K.t('ni')} ${x.ni}, ${K.t('poor')} ${x.poor}`)}">${seg('good','success')}${seg('ni','warning')}${seg('poor','danger')}</div>
